CREATE SCHEMA IF NOT EXISTS gamesboy;
SET search_path TO gamesboy, public;

-- 1. CORRECCIÓN Y NORMALIZACIÓN DEL ROL DE ADMINISTRADOR MASTER
-- (Permite tanto 'admin' como 'superadmin' para garantizar acceso al portal)
DO $$
BEGIN
    -- Eliminar restricción rígida previa de rol si existía
    ALTER TABLE IF EXISTS gamesboy.gb_users DROP CONSTRAINT IF EXISTS gb_users_role_check;
    ALTER TABLE IF EXISTS gamesboy.gb_users DROP CONSTRAINT IF EXISTS gb_users_role_key;
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

-- Asegurar usuario administrador master con rol 'admin'
INSERT INTO gamesboy.gb_users (id, tenant_id, name, email, role, avatar)
VALUES (
    'usr_admin',
    'tnt_gamesboy_main',
    'Admin GamesBoy',
    'admin@gamesboy.net',
    'admin',
    '/assets/branding/icon.png'
)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    email = EXCLUDED.email,
    role = 'admin',
    avatar = EXCLUDED.avatar;

UPDATE gamesboy.gb_users 
SET role = 'admin' 
WHERE email = 'admin@gamesboy.net' OR id = 'usr_admin';

